/*
=================================================================
  CALL CENTER DATABASE  —  SQL Server
  Author     : Mahmoud Metawea

  Built to reflect the kind of operational data I have worked
  with across 6+ years in BPO and contact centre environments.
  The schema, KPI definitions, and target benchmarks are based
  on real reporting requirements from inbound/outbound operations
  in the UAE telecom sector.

  Date Range (Calls) : 01 Jan 2024 – 31 Mar 2025  (12,000 call records)
  Date Range (dim_date) : 01 Jan 2024 – 31 Dec 2025  (extended for Power BI time intelligence)
  Rows       : 12,000 calls
  Schema     : Star Schema (1 Fact + 7 Dimensions)
-----------------------------------------------------------------
  DATA ACCURACY
  • SLA_Met   : Wait_Time_Sec <= 20 sec = Met
  • AHT       : Avg ~8 min — targets set per-queue to reflect data
  • Weekend   : Saturday + Sunday ONLY (UAE post-Jan 2022)
  • Abandoned : Handle/Talk/Hold/ACW = 0, Agent = NULL, SLA = No
  • Voicemail : Talk = 0, Hold = 0, no CSAT/NPS recorded.
              SLA applies — some customers opted into voicemail within the SLA window.
-----------------------------------------------------------------
  SECTIONS
  1  Database & schema setup
  2  Dimension tables + data  (incl. dim_targets)
  3  Fact table + data
  4  Indexes
  5  Data quality checks & cleaning
=================================================================
*/

-- =================================================================
-- SECTION 1: DATABASE SETUP
-- =================================================================

USE master;
GO

IF EXISTS (SELECT 1 FROM sys.databases WHERE name = 'CallCenterDB')
BEGIN
    DROP DATABASE CallCenterDB;
END
GO

CREATE DATABASE CallCenterDB;
GO

USE CallCenterDB;
GO

-- =================================================================
-- SECTION 2: DIMENSION TABLES
-- =================================================================

CREATE TABLE dbo.dim_agent (
    agent_id    VARCHAR(10)   NOT NULL CONSTRAINT pk_agent PRIMARY KEY,
    agent_name  NVARCHAR(100) NOT NULL
);

GO

CREATE TABLE dbo.dim_queue (
    queue_id   INT           NOT NULL CONSTRAINT pk_queue PRIMARY KEY,
    queue_name NVARCHAR(100) NOT NULL CONSTRAINT uq_queue_name UNIQUE
);

GO

CREATE TABLE dbo.dim_channel (
    channel_id   INT          NOT NULL CONSTRAINT pk_channel PRIMARY KEY,
    channel_name NVARCHAR(50) NOT NULL
);

GO

CREATE TABLE dbo.dim_product (
    product_id   INT           NOT NULL CONSTRAINT pk_product PRIMARY KEY,
    product_name NVARCHAR(100) NOT NULL
);

GO

CREATE TABLE dbo.dim_location (
    location_id      INT           NOT NULL CONSTRAINT pk_location PRIMARY KEY,
    city             NVARCHAR(100) NOT NULL
);

GO

-- is_weekend: 1 = Saturday or Sunday only (UAE post-Jan 2022 standard)

CREATE TABLE dbo.dim_date (
    date_key    DATE          NOT NULL CONSTRAINT pk_date PRIMARY KEY,
    [year]      SMALLINT      NOT NULL,
    quarter     CHAR(2)       NOT NULL,
    [month]     TINYINT       NOT NULL,
    month_name  NVARCHAR(20)  NOT NULL,
    day_of_week NVARCHAR(20)  NOT NULL,
    is_weekend  BIT           NOT NULL
);

SET DATEFIRST 7; -- Sunday = 1, Saturday = 7
GO

DECLARE @date DATE = '2024-01-01';
DECLARE @end  DATE = '2025-12-31';

WHILE @date <= @end
BEGIN
        @date,
        YEAR(@date),
        'Q' + CAST(DATEPART(QUARTER, @date) AS CHAR(1)),
        MONTH(@date),
        DATENAME(MONTH,    @date),
        DATENAME(WEEKDAY,  @date),
        CASE WHEN DATEPART(WEEKDAY, @date) IN (1, 7) THEN 1 ELSE 0 END
    );
    SET @date = DATEADD(DAY, 1, @date);
END
GO

-- AHT targets set to reflect actual data (~8 min avg):
-- Technical Support highest (diagnostic calls), Sales lowest (transactional)
CREATE TABLE dbo.dim_targets (
    target_id          INT           NOT NULL CONSTRAINT pk_targets PRIMARY KEY,
    queue_name         NVARCHAR(100) NOT NULL CONSTRAINT fk_targets_queue 
                                     REFERENCES dbo.dim_queue(queue_name),
    sla_target_pct     DECIMAL(5,1)  NOT NULL,
    aht_target_sec     INT           NOT NULL,
    csat_target        DECIMAL(4,2)  NOT NULL,
    fcr_target_pct     DECIMAL(5,1)  NOT NULL,
    abandon_target_pct DECIMAL(5,1)  NOT NULL
);

GO


-- =================================================================
-- SECTION 3: FACT TABLE
-- SLA_Met = 'Yes' when wait_time_sec <= 20 AND disposition != 'Abandoned'
-- =================================================================

CREATE TABLE dbo.fact_calls (
    call_id               VARCHAR(12)   NOT NULL CONSTRAINT pk_calls PRIMARY KEY,
    call_date             DATE          NOT NULL,
    call_datetime         DATETIME2(0)  NOT NULL,
    hour_of_day           TINYINT       NOT NULL,
    agent_id              VARCHAR(10)   NULL,
    queue_id              INT           NOT NULL,
    channel_id            INT           NOT NULL,
    product_id            INT           NOT NULL,
    location_id           INT           NOT NULL,
    customer_segment      NVARCHAR(50)  NOT NULL,
    disposition           NVARCHAR(50)  NOT NULL,
    sentiment             NVARCHAR(20)  NOT NULL,
    handle_time_sec       INT           NOT NULL DEFAULT 0,
    talk_time_sec         INT           NOT NULL DEFAULT 0,
    hold_time_sec         INT           NOT NULL DEFAULT 0,
    wait_time_sec         INT           NOT NULL DEFAULT 0,
    after_call_work_sec   INT           NOT NULL DEFAULT 0,
    csat_score            TINYINT       NULL,
    nps_score             TINYINT       NULL,
    -- first_call_resolution: agent-logged at call closure (Yes/No).
    -- NULL for Abandoned and Voicemail — resolution cannot be confirmed.
    first_call_resolution CHAR(3)       NULL,
    transferred           CHAR(3)       NOT NULL,
    sla_met               CHAR(3)       NOT NULL,
    CONSTRAINT fk_fc_agent    FOREIGN KEY (agent_id)    REFERENCES dbo.dim_agent(agent_id),
    CONSTRAINT fk_fc_date     FOREIGN KEY (call_date)   REFERENCES dbo.dim_date(date_key),
    CONSTRAINT fk_fc_queue    FOREIGN KEY (queue_id)    REFERENCES dbo.dim_queue(queue_id),
    CONSTRAINT fk_fc_channel  FOREIGN KEY (channel_id)  REFERENCES dbo.dim_channel(channel_id),
    CONSTRAINT fk_fc_product  FOREIGN KEY (product_id)  REFERENCES dbo.dim_product(product_id),
    CONSTRAINT fk_fc_location FOREIGN KEY (location_id) REFERENCES dbo.dim_location(location_id)
);
GO

