-- =================================================================
-- SECTION 4: INDEXES
-- =================================================================

CREATE NONCLUSTERED INDEX idx_call_date ON dbo.fact_calls (call_date);
CREATE NONCLUSTERED INDEX idx_agent_id ON dbo.fact_calls (agent_id);
CREATE NONCLUSTERED INDEX idx_disposition ON dbo.fact_calls (disposition);
CREATE NONCLUSTERED INDEX idx_sla_met ON dbo.fact_calls (sla_met);
CREATE NONCLUSTERED INDEX idx_first_call_resolution ON dbo.fact_calls (first_call_resolution);
GO

-- =================================================================
-- SECTION 5: DATA QUALITY CHECKS & CLEANING
-- =================================================================

-- -----------------------------------------------------------------
-- 5.1  Full data profile
-- -----------------------------------------------------------------
SELECT
    COUNT(*)                                                            AS total_rows,
    COUNT(DISTINCT call_id)                                             AS unique_call_ids,
    COUNT(*) - COUNT(DISTINCT call_id)                                  AS duplicate_count,
    SUM(CASE WHEN agent_id IS NULL
             AND disposition NOT IN ('Abandoned') THEN 1 ELSE 0 END)   AS missing_agent_connected,
    SUM(CASE WHEN csat_score IS NULL
             AND disposition NOT IN ('Abandoned','Voicemail')
             THEN 1 ELSE 0 END)                                         AS missing_csat,
    SUM(CASE WHEN nps_score IS NULL
             AND disposition NOT IN ('Abandoned','Voicemail')
             THEN 1 ELSE 0 END)                                         AS missing_nps,
    SUM(CASE WHEN first_call_resolution IS NULL
             AND disposition NOT IN ('Abandoned','Voicemail')
             THEN 1 ELSE 0 END)                                         AS missing_fcr,
    MIN(call_date)                                                      AS earliest_date,
    MAX(call_date)                                                      AS latest_date
FROM dbo.fact_calls;
GO

-- -----------------------------------------------------------------
-- 5.2  Verify weekend logic  (expect Saturday + Sunday only)
-- -----------------------------------------------------------------
SELECT day_of_week, is_weekend, COUNT(*) AS day_count
FROM dbo.dim_date
GROUP BY day_of_week, is_weekend
ORDER BY is_weekend DESC, day_of_week;
GO

-- -----------------------------------------------------------------
-- 5.3  Verify SLA threshold  (wait_time_sec <= 20 = Met)
-- -----------------------------------------------------------------
SELECT
    sla_met,
    MIN(wait_time_sec)  AS min_wait_sec,
    MAX(wait_time_sec)  AS max_wait_sec,
    AVG(wait_time_sec)  AS avg_wait_sec,
    COUNT(*)            AS call_count
FROM dbo.fact_calls
WHERE disposition != 'Abandoned'
GROUP BY sla_met
ORDER BY sla_met DESC;
GO

-- -----------------------------------------------------------------
-- 5.4  Detect duplicate Call_IDs
-- 
-- -----------------------------------------------------------------
WITH cte_duplicates AS (
    SELECT
        call_id,
        call_datetime,
        ROW_NUMBER() OVER (PARTITION BY call_id ORDER BY call_datetime) AS rn,
        COUNT(*) OVER (PARTITION BY call_id) AS occurrences
    FROM dbo.fact_calls
)
SELECT
    call_id,
    call_datetime,
    rn          AS row_number_within_group,
    occurrences AS total_copies
FROM cte_duplicates
WHERE occurrences > 1
ORDER BY call_id, rn;
GO

-- -----------------------------------------------------------------
-- 5.5  Remove duplicates — keep earliest record per Call_ID
-- -----------------------------------------------------------------
WITH cte_ranked AS (
    SELECT
        ROW_NUMBER() OVER (PARTITION BY call_id ORDER BY call_datetime) AS rn
    FROM dbo.fact_calls
)
DELETE FROM cte_ranked WHERE rn > 1;
GO


-- -----------------------------------------------------------------
-- 5.6  Check abandoned calls with non-zero metrics
-- -----------------------------------------------------------------
SELECT call_id, disposition, wait_time_sec,
       handle_time_sec, talk_time_sec, agent_id
FROM dbo.fact_calls
WHERE disposition = 'Abandoned'
  AND (handle_time_sec > 0 OR talk_time_sec > 0
    OR hold_time_sec   > 0 OR agent_id IS NOT NULL);
GO

-- -----------------------------------------------------------------
-- 5.7  Fix abandoned calls with incorrect metrics
-- -----------------------------------------------------------------
UPDATE dbo.fact_calls
SET handle_time_sec = 0, talk_time_sec = 0,
    hold_time_sec   = 0, after_call_work_sec = 0,
    agent_id        = NULL, sla_met = 'No'
WHERE disposition = 'Abandoned';
GO

-- -----------------------------------------------------------------
-- 5.8  Standardise disposition typos
-- -----------------------------------------------------------------
UPDATE dbo.fact_calls
SET disposition = CASE
    WHEN LOWER(TRIM(disposition)) IN ('resolved','resolve','resolvd')       THEN 'Resolved'
    WHEN LOWER(TRIM(disposition)) IN ('escalated','escalate','escaltaed')   THEN 'Escalated'
    WHEN LOWER(TRIM(disposition)) IN ('abandoned','abandonned','abandond')   THEN 'Abandoned'
    WHEN LOWER(TRIM(disposition)) IN ('transferred','transfered','transfrd') THEN 'Transferred'
    WHEN LOWER(TRIM(disposition)) IN ('call back','callback','call-back')    THEN 'Call Back'
    WHEN LOWER(TRIM(disposition)) IN ('voicemail','voice mail','voice-mail') THEN 'Voicemail'
    ELSE disposition
END;
GO

-- -----------------------------------------------------------------
-- 5.9  Null out out-of-range scores
-- -----------------------------------------------------------------
UPDATE dbo.fact_calls SET csat_score = NULL WHERE csat_score NOT BETWEEN 1 AND 5;
UPDATE dbo.fact_calls SET nps_score  = NULL WHERE nps_score  NOT BETWEEN 0 AND 10;
GO

-- -----------------------------------------------------------------
-- 5.10 Handle time less than talk time integrity check
-- -----------------------------------------------------------------
SELECT call_id, handle_time_sec, talk_time_sec, hold_time_sec
FROM dbo.fact_calls
WHERE handle_time_sec < talk_time_sec
  AND disposition NOT IN ('Abandoned','Voicemail');
GO

-- -----------------------------------------------------------------
-- 5.11 Null out FCR for abandoned and voicemail calls
--
--      first_call_resolution is not applicable for abandoned calls
--      (no agent interaction) or voicemail calls (resolution cannot
--      be confirmed). Setting to NULL ensures these calls are excluded
--      from the FCR denominator and do not distort the rate.
-- -----------------------------------------------------------------
UPDATE dbo.fact_calls
SET first_call_resolution = NULL
WHERE disposition IN ('Abandoned', 'Voicemail');
GO

-- Verify: expect 0 rows
SELECT call_id, disposition, first_call_resolution
FROM dbo.fact_calls
WHERE disposition IN ('Abandoned','Voicemail')
  AND first_call_resolution IS NOT NULL;
GO

